/**
 * The `scholarly_cite` tool: extracts official citations directly from DOI registration agencies.
 * Supports BibTeX, RIS, CSL JSON, and formatted references (APA, IEEE, Nature, GB/T 7714).
 * @module dsh-zotero/scholarly/tools/cite
 */

import { type ToolDefinition } from '@deepseek-ai/dsh-tools'
import { defineZoteroTool as defineTool } from '../../define-tool.js'
import { mapWithConcurrency } from '../../concurrency.js'
import { ZoteroError, ZOTERO_INVALID_ARGUMENT } from '../../errors.js'
import { parsePaperIdentifier } from '../fulltext/resolve.js'
import { httpStatusOf } from '../transport/http.js'
import { lookupEuropePmc } from '../sources/pmc.js'
import { validateCitation, type CiteFormat } from '../citation-format.js'
import { failureTextOf } from './failure.js'
import {
  SCHOLARLY_TEXT_OUTPUT_DESCRIPTOR,
  type ScholarlyToolHost,
  type ScholarlyToolOutput,
} from './common.js'

/**
 * The content-negotiation `accept` value for each non-prose format.
 *
 * Typed as a total map over the formats that need one: a format added to the
 * tool without an entry here is a compile error, not an `undefined` header that
 * quietly negotiates the registry's default representation.
 */
const FORMAT_MIME_TYPES: Record<Exclude<CiteFormat, 'text'>, string> = {
  bibtex: 'application/x-bibtex',
  ris: 'application/x-research-info-systems',
  csljson: 'application/vnd.citationstyles.csl+json',
}

/** Per-call identifier cap; the description promises it and the executor enforces it. */
const SCHOLARLY_CITE_MAX_IDS = 30

/**
 * One identifier's outcome. Every submitted ID produces exactly one item in
 * input order, preserving partial failures alongside successful results.
 */
type CiteOutcome =
  | { status: 'resolved'; requestedId: string; value: string; resolvedDoi: string }
  | { status: 'failed'; requestedId: string; reason: string }

export function createScholarlyCiteTool(host: ScholarlyToolHost): ToolDefinition {
  return defineTool({
    name: 'scholarly_cite',
    description:
      'Get exact official citations directly from DOI registration registries (doi.org): ' +
      'BibTeX, RIS, CSL JSON, or formatted references in any CSL citation style. ' +
      'Always use this tool instead of writing BibTeX entries or citations from memory.',
    parameters: {
      ids: {
        type: 'array',
        required: true,
        items: { type: 'string' },
        description: `DOIs, arXiv IDs, or PMIDs (up to ${SCHOLARLY_CITE_MAX_IDS} items).`,
      },
      format: {
        type: 'string',
        required: true,
        enum: ['bibtex', 'ris', 'csljson', 'text'],
        description: 'Citation format: bibtex, ris, csljson, or text (formatted reference).',
      },
      style: {
        type: 'string',
        default: 'apa',
        description:
          'CSL style ID for format="text", e.g. apa, ieee, nature, china-national-standard-gb-t-7714-2015-numeric.',
      },
      locale: {
        type: 'string',
        description: 'Language locale for format="text" terms, e.g. zh-CN, en-US.',
      },
    },
    output: SCHOLARLY_TEXT_OUTPUT_DESCRIPTOR,
    isConcurrencySafe: () => true,
    timeoutMs: 120_000,
    async execute(args, exec): Promise<ScholarlyToolOutput> {
      const style = args.style?.trim() || 'apa'
      const acceptHeader =
        args.format === 'text'
          ? `text/x-bibliography; style=${style}${args.locale ? `; locale=${args.locale}` : ''}`
          : FORMAT_MIME_TYPES[args.format]

      if (!args.ids || args.ids.length === 0) {
        throw new ZoteroError('ids parameter cannot be empty.', ZOTERO_INVALID_ARGUMENT)
      }
      // The cap is part of the tool's contract, so exceeding it is a named
      // refusal: silently dropping ids would answer a different question
      // than the one asked.
      if (args.ids.length > SCHOLARLY_CITE_MAX_IDS) {
        throw new ZoteroError(
          `ids accepts at most ${SCHOLARLY_CITE_MAX_IDS} identifiers per call; got ${args.ids.length}. Split the list across calls.`,
          ZOTERO_INVALID_ARGUMENT,
        )
      }

      const targets = args.ids
      const keys = await host.keys()

      const outcomes = await mapWithConcurrency(
        targets,
        5,
        async (raw, signal): Promise<CiteOutcome> => {
          const id = parsePaperIdentifier(raw)
          let doi: string | undefined =
            id?.kind === 'doi'
              ? id.id
              : id?.kind === 'arxiv'
                ? `10.48550/arXiv.${id.id}`
                : undefined

          try {
            if (!doi && (id?.kind === 'pmid' || id?.kind === 'pmcid')) {
              const pmc = await lookupEuropePmc(
                id.kind === 'pmid' ? { pmid: id.id } : { pmcid: id.id },
                host.http,
                keys,
                signal,
              )
              doi = pmc?.doi
            }

            if (!doi) {
              return {
                status: 'failed',
                requestedId: raw,
                reason:
                  'No DOI found for this item, cannot query registry citation. Use scholarly_get to resolve metadata before retrying scholarly_cite.',
              }
            }

            const safeDoi = doi.split('/').map(encodeURIComponent).join('/')
            const body = await host.http.text(`https://doi.org/${safeDoi}`, {
              headers: { accept: acceptHeader },
              signal,
              retries: 1,
            })

            // Validate both the requested format and DOI before accepting the
            // response as a citation.
            const validation = validateCitation(args.format, body, doi)
            if (!validation.ok) {
              return { status: 'failed', requestedId: raw, reason: validation.reason }
            }
            return {
              status: 'resolved',
              requestedId: raw,
              value: validation.value,
              resolvedDoi: validation.resolvedDoi,
            }
          } catch (error) {
            if (signal.aborted) throw error
            const status = httpStatusOf(error)
            return {
              status: 'failed',
              requestedId: raw,
              reason: status === 404 ? 'DOI does not exist on doi.org' : failureTextOf(error),
            }
          }
        },
        { signal: exec.signal },
      )

      const values: string[] = []
      const issues: string[] = []
      const citations = outcomes.map((outcome, inputIndex) => {
        if (outcome.status === 'resolved') values.push(outcome.value)
        else issues.push(`#${inputIndex + 1} ${outcome.requestedId}: ${outcome.reason}`)
        return { inputIndex, ...outcome }
      })

      const label = args.format === 'text' ? `style ${style}` : args.format
      const separator = args.format === 'text' ? '\n' : '\n\n'
      const summary = `Citations from official DOI registries (${label}): ${values.length} of ${targets.length} resolved.`
      const problemsText =
        issues.length > 0
          ? `\nUnresolved items:\n${issues.join('\n')}\nNext: use scholarly_get to check alternate-index metadata before treating an item as absent.`
          : ''

      return {
        text: `${summary}\n\n${values.join(separator)}${problemsText}`,
        citations,
        issues,
      }
    },
    presentCall: (args) => ({
      card: 'generic',
      title: 'Format scholarly citations',
      rawInput: String(args.format ?? 'bibtex'),
      kind: 'read',
    }),
  })
}
